   await tx(x=>{x.questions=[{id:'result_input',text:result.uncertainties.filter(u=>u.material).map(u=>u.text).join('; ')||result.summary,reason:'MISSING_DATA'}];x.phase='WAITING_FOR_USER';return null;});return;
