   autoExact(intake,['kind','reply']);autoNeed(['CHAT','GOAL','ANSWER'].includes(intake.kind),'AUTO01_INTAKE');autoText(intake.reply);
   await tx(x=>{x.history=appendMessage(x.history,'msg_'+(x.history.length+1),'assistant',intake.reply);if(intake.kind!=='CHAT')x.original_request??={message_id:userId,text,hash:digest(text)};return null;});
